export const awaken_beastie = <>A beast is permanently awakened to sentience, gaining +3 to <Sub attr="INT"/> and +3 to <Sub attr="CHA"/> in addition to the ability to speak. It automatically joins you in combat, unless mortally afraid. After one week of sentience, the animal must make a DT 14 <Sub attr="CHA"/> saving throw or be overcome with existential angst, whereupon it will plead the caster to revoke sentience (which is done by casting the spell a second time).</>

export const oneiromancy = <>During the ritual, the caster beseeches the fey for a vision concerning an important topic, and then falls into a magical slumber. While asleep, the caster receives a vision. The DM privately rolls a d20, which determines how directly the vision answers the question. On a 1, the vision (fantastical as it may be) bears absolutely no relation to the question at hand, and may even be malicious fey trickery.</>

export const sweet_dreams = <>You and all participants call out to the fey, thanking them for their role in maintaining the balance of nature and protecting the life force. You invite them to visit you in your dreams, calling for succor, entertainment, and guidance. All participants roll a 1d4, and gain an effect accordingly: <ol><li>Hellish Nightmares: Tormented by cruel fey, no rest can be had. No Willpower is recovered during the long rest.</li><li>Vivid Visions: Playful and adventurous fey take the dreamer on wondrous adventures seeming to last for many days. Upon awakening, the individual gains 1d4 temporary willpower.</li><li>Quiet Quandaries: The dreamer awakens beside a pool of water, which idly asks the dreamer a question. After it has been answered, it invites the dreamer to ask a question of their own. If the adventurer answered the water's question truthfully, it answers truthfully. Also gain 1d6 temporary WP.</li><li>Allmother's Embrace: The dreamers is escorted by powerful fey to the magical heart of the forest. They are greeted by a gentle yet powerful dryad called the Allmother, who embraces them tenderly. Gain 1d8 temporary HP and willpower.</li></ol></>

export const primal_form = <>The caster expends 10 willpower to transform into a more primal version of their race for one hour. For example, a human, elf, dwarf, or halfling would become a neanderthal. The caster gains +5 <Sub attr="STR"/>, and +2 <Sub attr="NST"/> but suffers -5 <Sub attr="INT"/> and -2 <Sub attr="CHA"/> for the duration of the spell. You lose one level of proficiency in every skill for the duration of the spell.</>

export const forest_defender = <>An allied animal (recruited via <AppendixLink appendix={1} target="beast_speech">Beast Speech</AppendixLink> or <AppendixLink appendix={1} target="awaken_beastie">Awaken Beastie</AppendixLink>) grows to twice its normal size. Such a creature gains +10 <Sub attr="STR"/>.</>

export const fairys_feast = <>The fairies bring forth a great feast, consisting of fruits and vegetables, wine, cheeses, and venison. The feast serves up to a dozen men, and all who partake become immune to disease and poison (and cured thereof) for eight hours, and also heal 3d20 hp. The feast also alleviates two levels of hunger. After one hour, the entire repast vanishes without a trace.<br /><b>But beware!</b> If anyone partakes and forgets to thank the fairies, they shall suffer one of the following curses for 1 hour (chosen randomly):<ol><li>Shrunken to the size of a rat</li><li>Beset with bizarre illusions and hallucinations</li><li>Plagued with swarms of gnats and biting flies</li><li>Loss of sight and hearing</li><li>Dreadful nightmares and intrusive thoughts most vile</li><li>Gnawing hunger, which is not sated by any amount of food or drink</li></ol></>

export const dream_warrior = <>During the next long rest following the ritual, you dream of a warrior spirit who will assist you in times of hardship. You may determine the warrior's race, class, and level, though their level is limited to half of yours. When you awake in the morning, you will find at your side a glittering silver hand bell. When you ring this bell, you may expend willpower (equal to twice their level) to summon this warrior to your side for eight hours. Performing this ritual a second time causes the first bell to disappear.</>

export const monkeys_paw = <>Three individuals wish upon the severed paw of a monkey, gaining one wish each. Each one who would wish rolls a d20; the number shown is the number of words they may use to construct their wish. Each wish is sure to come true, but the execution is left to the caprice of powerful fairy. A given individual may partake three times of this ceremony, ere the fey turn a deaf ear to their pleas.</>

export const find_familiar = <>The caster summons a lesser spirit as a familiar. The spirit takes the form of an imp, a pseudodragon, or a chupacabra.</>

export const mage_hand = <>The caster expends 1 willpower to summon a floating spectral hand. The hand is a minor spirit, obedient and sentient but prone to occasional unbidden mischief. The hand can fly up to 100 yards away from its master, and carry an object weighing up to five pounds.</>

export const summon_weapon = <>Summon a small or standard weapon to hand for one hour. The weapon is partially transparent, ever burning with an eerie violet flame. The weapon deals the same damage as a weapon of steel.</>

export const locust_swarm = <>A swarm of biting locusts swarms around a target, dealing 2d6 <span style={{color: "#FFF"}}>Piercing</span> damage. The spell also has a chance to inflict <Tooltip tip={"Poisoned"}>After a set amount of time, the poison takes hold. The exact effect depends on the type of poison.</Tooltip>,</>

export const imbue_sentience = <>A minor spirit is bound to an inanimate object weighing less than one ton. TODO</>

export const soul_dart = <>The caster imbues some of their life force into a number of spectral darts, up to four. Lose 1 hp and one willpower for each dart summoned. Each dart deals 1d6 piercing damage on a hit, and cannot miss.</>

export const sentient_weapon = <>The spirit of a fallen warrior is summoned from the astral to imbue a summoned weapon with sentience for one hour. The spirit possess a weapon summoned with <AppendixLink appendix={1} target="summon_weapon">Summon Weapon</AppendixLink>, and causes it hover in place and attack on its own.</>

export const exorcism = <>The caster attempts to purge a demon or unnatural host from a possessed body. The caster rolls for <Sub skill="Sorcery" /> while the possessing spirit rolls for <Sub attr="NST"/>. If the caster rolls higher, the spirit is cast out, unless it is extremely powerful.</>

export const cloud_of_daggers = <>Summon dozens of daggers from the astral plane begin to swirl around the designated region. Creatures within take 2d4 slashing and 2d4 piercing damage per turn.</>

export const demonic_posession = <>The caster calls forth a lesser demon and commands it to bind the chosen creature. The demon attempts possession, rolling for <Sub attr="CHA"/> against the victim's current willpower. If successful, the target is possessed for one hour, at which point they may make an additional saving throw to escape possession.</>

export const invade_body = <>The caster identifies a victim and attempts to permanently enter their body. The caster rolls for <Sub skill="Sorcery" /> against the target's willpower score. If successful, the victim is abruptly torn from their body and cast into the astral plane, while their attacker inhabits their body. If this spell is cast successful while already incarnate, the caster's previous body suffers cardiac arrest and undergoes irreversible damage after 2d6 minutes.</>

export const reincarnation = <>Draconic spirits answer the ceremonial call, allowing a living and a deceased soul exchange places. The reincarnated spirit inhabits the new body, while the sacrificial participant departs into the astral plane as a servant of dragons. The dragons accept only willing sacrifices, but otherwise do not question the methods of the ceremony. Once reincarnated, the soul retains both their old memories and those of the body's original inhabitant.</>

export const resurrection = <>A deceased soul is returned to its body and made whole again, in a manner holy and pure. If the soul's body was destroyed, a new one in the same likeness is formed. The spirit to be resurrected must be good aligned. Otherwise, the leader must pass a DT 18 <Sub skill="Persuasion" /> check to persuade the angels that it is righteous to make an exception and overturn the course of nature. If the spirit to resurrect is evil, the</>

export const guidance = <>The caster touches an ally, giving them a 1d4 bonus to ability checks and saving throws for one round.</>

export const alarm = <>A minor spirit is infused into an object, keeping watch. If the spirit observes unexpected or suspicious behavior, it begins to screech as loudly as possible. Each minor spirit has its own manner of screeching, but they are invariably extremely loud and annoying. The spirit can respond to simple instructions once summoned, regarding when to remain silent, screech, or abandon its post. If the spell <AppendixLink appendix={1} target="minor_telepathy">Minor telepathy</AppendixLink> is known, the spirit can be instructed to transmit a silent telepathic alarm instead. If the spell <AppendixLink appendix={1} target="major_telepathy">Major Telepathy</AppendixLink> is known, it can also communicate details about the situation when the alarm is triggered.</>

export const detect_magic = <>You detect the presence of any ongoing spells. You may also detect</>

export const seek_spirit = <>The caster enters a meditative state and calls out for assistance, either to angels, demons, or dragons. Up to three entities are called forth, identifying themselves by name, but not by rank or alignment. The caster may ask each entity three questions, in order to discern its nature. The questions are limited to hypotheticals. The caster remembers the names of these principalities and powers, whose names he may later call upon in times of need.</>

export const seance = <>The caster enters a state of focus, sitting in a quiet and darkened room scented with incense. The caster calls a departed soul by name and asks them to come forward. A spirit responds and may answer questions, but might not answer truthfully or be the one which was called. The caster can attempt a DT 16 <Sub skill="Perception" /> (CHA) check to determine if the spirit has lied at any point so far during the ritual. Detecting a liar banishes the spirit but does not necessarily end the seance.</>

export const diagnose = <>Gain insight into the remaining hitpoints and willpower of an enemy monster.</>

export const soul_sight = <>For one hour, gain the ability to perceive latent spirits and the lingering deceased.</>

export const augury = <>TODO</>

export const astral_projection = <>The caster enters a meditative state and enters the astral plane, the realm ordinarily accessible only to disincarnate entities. The nature of the astral is elucidated in <AppendixLink appendix={6}>Appendix: Bestiary</AppendixLink>. While in the astral, the caster may explore the lower astral to perceive a distorted version of the physical plane, or venture into the higher astral and converse with various entities in their natural environs, and request their names for summoning purposes.</>

export const ancient_name = <>The ritual establishes an audience with an ancient and mighty spirit: a dragon, an archdemon, or an angel. Each type of spirit must be plied by a valuable thing of a specific kind: the dragon, by gold. The demon, by the blood of innocents. The angel, by sincerity and a pure heart. If the offering is lacking in quality or quantity, the spirit chastises the summoner and explains by what terms, if any, the spirit may be plied. If successful, the spirit joins the player as a summon for eight hours. The spirit fights at the player's side and is true to their word, but acts of their own volition otherwise.</>

export const futuresight = <>The player gains the ability to foresee events before they occur. For one hour, the player may see the result of skill checks before the underlying action is undertaken.</>

export const vampiric_touch = <>A target you touch is putrefied with necrotic energy. The target takes 1d8 <span style={{color: "#92F"}}>Profane</span> damage, while you are healed by the same amount of damage dealt.</>

export const life_leach = <>A ray of black energy arcs from the hands of the caster to their target. The target takes 1d4 <span style={{color: "#92F"}}>Profane</span> damage on the first turn the spell is cast and 1d6 damage on subsequent turns. The healer is healed by 1 for every point of damage dealt.</>

export const reanimate = <>A bestial or humanoid creature is returned to an eerie semblance of life.</>

export const inflict_disease = <>A target you choose potentially becomes afflicted by one of a number of diseases, with symptoms appearing within one hour if the target  fails a DT 10 <Sub skill="Defense" /> saving throw. The target becomes <Tooltip tip={"Lethargic"}>The target must expend willpower to take the move action. All willpower is exhuasted if traveling more than one mile on foot. The target also has disadvantage on skill checks and saving throws.</Tooltip> for 1d8 days.</>

export const hex = <>Cruel magic inflicts a lasting disability upon the target, hampering their use of a chosen skill. The target gains disadvantage on checks with that skill until they are cleansed by a priest or sprinkled with holy water.</>

export const starvation = <>The target gains one level of starvation, as if it had gone a day without consuming food.</>

export const speak_with_the_dead = <>A dead body is used as conduit to contact a departed soul. The soul is torn across time and space and wrenched back into its former body in order to answer up to three questions. Afterwards, its body crumbles into dust. If the soul is incarnated, its current body falls unconscious while this spell is cast.</>

export const curse = <>The target is cursed with a cruel and lasting affliction of one of the following types: TODO</>

export const disintegrate = <>A ray of dark black and green energy arcs towards a target. The target takes 3d12 <span style={{color: "#92F"}}>Profane</span> damage if it is living, or disintegrates into a pile of ash if it is inanimate.</>

export const vampiric_kiss = <>Transfer up to 6 willpower to or from a target you can touch. If the target is willing, the spell costs no willpower. If not, you must grapple the target before casting the spell.</>

export const devour = <>Inflict 2d6 <span style={{color: "#92F"}}>Profane</span> damage on a target. If the spell lands a killing blow, gain their remaining willpower.</>

export const rend_soul = <>Deal 4d12 <span style={{color: "#92F"}}>Profane</span> damage to a target within 100 yards. If a target is slain as a result of this spell, the caster may immediately enter its body.</>

export const flesh_golem = <>A repulsive mountain of pulsating organs and exposed muscle is summoned to do its master's bidding.</>

export const become_lich = <>The caster prepares a number of vessels, called phylacteries, to anchor the components of their soul to the physical plane. For every phylactery, a sentient mortal life (willing or unwilling) is sacrificed, to provide the necessary magical binding energy. A minimum of three sacrifices is required, to complete the ritual. The sacrificial victims contribute their willpower towards the completion of the ritual. When the ceremony is complete, the caster becomes a lich, a sentient undead with a lifespan of 666 years. Repeating the ritual extends lifespan by an additional 666 years, but requires twice as many sacrifices each time.</>

export const heat_metal = <>A piece of metal such as a weapon or suit of armor becomes unbearably hot. If the item is worn or carried, the wearer takes 2 <span style={{color: "#F80"}}>Heat</span> damage, which increases by 2 each turn to a maximum of 8 <span style={{color: "#F80"}}>Heat</span> damage per turn.</>

export const mend = <>The caster magically repairs a small wound, crack, or tear in a person or object. The target must be smaller than one cubic foot of volume.</>

export const clay_armor = <>The caster's skin becomes hardened clay for one hour, improving BC by 5.</>

export const quake = <>The caster concentrates on accumulating seismic forces within the earth. A patch of ground with a radius of 10 feet begins to tremble and undulate noticeably. When the spell is ended, all targets within 30 feet of the caster take 1d10 <span style={{color: "#D00"}}>Force</span> damage for every turn concentration was maintained.</>

export const quicksand = <>Transform solid ground into sinking sand. The affected area becomes difficult terrain. Additionally, targets which start their turn on the quicksand must make a DT 14 <Sub skill="Mobility" /> saving throw or lose the ability to move.</>

export const acid_blade = <>Imbue a blade you touch with the power of acid. For one hour, attacks with the weapon deal 1d4 <span style={{color: "#AF0"}}>Acid</span> damage and decrease enemy BC by 1.</>

export const clay_golem = <>A clay golem is summoned for 8 hours. Though the weakest of the golems, it has resistance to <span style={{color: "#888"}}>Bludgeoning</span> and <span style={{color: "#FFF"}}>Piercing</span> damage due to its soft body.</>

export const stone_armor = <>The caster's skin becomes brittle stone, improving BC by 7. The armor shatters after 10 <span style={{color: "#888"}}>Bludgeoning</span> damage is taken, ending the spell.</>

export const earthen_wall = <>A great earthen wall up to 100 feet long appears in the indicated location, obstructing movement. The wall can absorb 50 damage before it breaks, and is immune to <span style={{color: "#F80"}}>Heat</span> damage. Targets over the area where the wall was constructed are pushed aside.</>

export const stone_golem = <>Summon a stone golem. The golem is vulnerable to <span style={{color: "#888"}}>Bludgeoning</span> damage, but resistant to <span style={{color: "#FFF"}}>Piercing</span> damage.</>

export const iron_armor = <>Your skin becomes covered by a magical metallic liquid. The liquid condenses and becomes firm wherever an arrow, missile, or blade would strike true. Block Chance is increased by 10.</>

export const awaken_statue = <>A statue you touch comes to life for one hour. The statue may assist you in battle or inform you events that have transpired since it was built.</>

export const earthquake = <>The ground around you rumbles and shakes, as your spell unleashes a mighty earthquake. Creatures within 300 yards take 3d12 <span style={{color: "#D00"}}>Force</span> damage and have disadvantage on the saving throw to avoid being knocked prone.</>

export const iron_golem = <>Summon a heavy iron golem, heaviest of the golems.</>

export const petrify = <>Transform a creature of living flesh into stone. The creature may make a DT 10 <Sub skill="Defense" /> saving throw to resist this effect.</>

export const mote_o_fire = <>A mote of fire alights in your hand, hovering gently. The flame can be held for illumination, or thrown at an enemy within 30 feet. If thrown, roll for <Sub skill="Accuracy" /> again your target. On a hit, it takes 2d6 <span style={{color: "#F80"}}>Heat</span> damage.</>

export const arcane_flames = <>Flowing flames surge from your outstretched hands, dealing 3d6 <span style={{color: "#F80"}}>Heat</span> damage to all creatures caught in the blaze.</>

export const flame_armor = <>Wreath your body in flame. The spell does not increase your Block Chance, but causes enemies that start or end their turn next to you to take 1d12 <span style={{color: "#F80"}}>Heat</span> damage.</>

export const flaming_sword = <>For one hour, A blade is imbued with the power of arcane fire. The blade deals 1d6 additional <span style={{color: "#F80"}}>Heat</span> damage.</>

export const fireball = <>Hurl a blazing ball of fire which explodes upon impact. Roll for <Sub skill="Accuracy" /></>

export const incinerate = <>An flame of exceptional heat deals 2d12 <span style={{color: "#F80"}}>Heat</span> damage to a target within 15 feet.</>

export const create_lava = <>Create a mass of lava, able to cover 100 square feet of terrain. Creatures which start or end their turn on lava take 3d6 <span style={{color: "#F80"}}>Heat</span> damage.</>

export const fire_elemental = <>Summon a fire elemental. It knows the spells <AppendixLink appendix={1} target="mote_o_fire">Mote o' Fire</AppendixLink>, <AppendixLink appendix={1} target="arcane_flames">Arcane Flames</AppendixLink> and <AppendixLink appendix={1} target="fireball">Fireball</AppendixLink>, and has a continual flame cloak as if it had cast <AppendixLink appendix={1} target="flame_armor">Flame Armor</AppendixLink>.</>

export const flame_wall = <>A wall of flames, 20 feet in height, surges up from scorched and blackened ground. Creatures which pass through the wall take 3d12 <span style={{color: "#F80"}}>Heat</span> damage. Any creatures standing where the wall is cast take 2d12 <span style={{color: "#F80"}}>Heat</span> damage.</>

export const fire_storm = <>Pure flame explodes from the caster bringing glorious devastation. The caster deals 4d20 <span style={{color: "#F80"}}>Heat</span> damage to all creatures within 50 feet.</>

export const fire_golem = <>The ritual summons a fire golem, the most volatile of the golems.</>

export const frostbite = <>A conical spray of frost deals 1d6 <span style={{color: "#4BF"}}>Cold</span> damage to all enemies caught within.</>

export const shape_water = <>You may shape water into a form you choose, and freeze so that it retains its form. This spell can manipulate, freeze, or melt up to 100 pounds of water per cast.</>

export const icicle = <>An icy spear is hurled at a foe, dealing 1d8 <span style={{color: "#FFF"}}>Piercing</span> and 1d6 <span style={{color: "#4BF"}}>Cold</span> damage.</>

export const water_walking = <>For one hour, you gain the ability to walk on water as if it were solid ground. When the spell is about to expire, the water's surface betakes a spongy and soft texture, as if it were thick mud or bedding. If cast while the mage is partially submerged, you are propelled to the surface of the water. If fully underwater, the spell has no effect. You do not take fall damage if you cast this spell before falling onto the surface of the water.</>

export const ice_elemental = <>Summon and bid an ice elemental from the plane of water. The ice elemental knows the spells <AppendixLink appendix={1} target="frostbite">Frostbite</AppendixLink>, <AppendixLink appendix={1} target="icicle">Icicle</AppendixLink>, <AppendixLink appendix={1} target="water_walking">Water Walking</AppendixLink>, and <AppendixLink appendix={1} target="become_water">Become Water</AppendixLink>.</>

export const steam_blast = <>A gout of pressurized steam spouts from your outstretched hand, dealing 1d10 <span style={{color: "#F80"}}>Heat</span> damage and 1d10 <span style={{color: "#D00"}}>Force</span> damage. The heat damage dealt by this spell does not inflict <Tooltip tip={"Burning"}>Accumulates. Characters take 1d4 damage at the end of their turn, then lose one level of burning. If accumulated burning exceeds the target's Strength score at the start of their turn, they are incapacitated for that turn.</Tooltip>.</>

export const ice_wall = <>Construct a wall of ice, one yard thick and up to 10 yards in length. Creatures inside the wall when it forms must make a DT 8 <Sub skill="Mobility" /> saving throw or become encased in the wall for the duration of the spell. Creatures which pass the saving throw may choose to stand on top of the wall or be pushed to one side.</>

export const wellspring = <>Water spouts forth from a point designated by the caster, releasing up to 10 gallons per minute.</>

export const become_water = <>The caster becomes liquid water for up to eight hours, able to flow and reform according to their will.</>

export const ice_armor = <>Encase yourself in armor of solid ice. You gain immunity to <span style={{color: "#4BF"}}>Cold</span> damage and you BC increases by 7. The spell lasts for 1 minute or until you take 10 <span style={{color: "#888"}}>Bludgeoning</span> damage.</>

export const blizzard = <>You summon a small blizzard, creating a region of extremely frigid air within a radius of 100 feet that lasts for 1 hour. Targets within take 1d12 <span style={{color: "#4BF"}}>Cold</span> damage and 1d12 <span style={{color: "#D00"}}>Force</span> damage per turn.</>

export const ice_golem = <>Summon and bid a powerful ice golem.</>

export const ice_statue = <>An enemy makes a DT 16 <Sub skill="Defense" /> aving throw or is instantaneously encased into a block of ice. On a successful save, the target accumulates 3 levels of <Tooltip tip={"Freezing"}>Accumulates. The target's Dexterity is reduced by 1 for each turn of accumulated freezing. Freezing decreases by 1 at the end of every turn.</Tooltip> instead. If this is sufficient to trigger the <Tooltip tip={"Frozen"}>The target is encased in ice and incapacitated. They become vulnerable to Force and Bludgeoning, but resistant to all other forms of damage.</Tooltip> status, then so be it.</>

export const tsunami = <>A great wall of water appears, sweeping across the battlefield in a wide berth 100 feet wide. Targets take 4d10 <span style={{color: "#D00"}}>Force</span> damage and must make a DT 20 <Sub skill="Mobility" /> saving throw or be pushed up to 100 yards by the wall of water.</>

export const thunderbolt = <>A bolt of lightning from the heavens strikes a single enemy, dealing 1d10 damage.</>

export const electrocute = <>Attempt an unarmed attack on an opponent. On a success, deal 1d8 <span style={{color: "#FF4"}}>Lightning</span> damage in addition to your normal damage.</>

export const cyclone = <>A swiftly swirling whirlwind forms in the location you choose. On your turn, you can move the cyclone along a path up to 20 feet in length, dealing 2d6 <span style={{color: "#D00"}}>Force</span> damage to each target hit.</>

export const shocking_blade = <>Imbue a metallic weapon you can touch with the power of lightning. The weapon deals 1d6 <span style={{color: "#FF4"}}>Lightning</span> damage for one hour.</>

export const blustering_gust = <>A gust of wind blusters forth, dealing no damage but pushing enemies about. An enemy caught in the gust is pushed 20 feet in the direction of the gust. On a successful DT 10 <Sub skill="Defense" /> saving throw, the target is only pushed half that distance.</>

export const soar = <>Gain the ability of wingless flight for five minutes. While the spell is active, you may move through the air at 15 feet per second.</>

export const lightning_dash = <>Teleport to a location you can see within 15 feet. If any enemies are between you and your destination, they take 1d12 <span style={{color: "#FF4"}}>Lightning</span> damage.</>

export const air_elemental = <>Summons an air elemental to do your bidding. The elemental knows <AppendixLink appendix={1} target="blustering_gust">Blustering Gust</AppendixLink>, <AppendixLink appendix={1} target="soar">Soar</AppendixLink>, <AppendixLink appendix={1} target="lightning_dash">Lightning Dash</AppendixLink>, abd <AppendixLink appendix={1} target="thunderbolt">Thunderbolt</AppendixLink>.</>

export const become_vapor = <>Become a cloud of vapor. You become immune to slashing, piercing, and bludgeoning damage. You may change your shape to fit around or between narrow obstacles or enemies. You may not delve underwater, and if this spell is cast underwater, you automatically shoot to the surface.</>

export const chain_lighting = <>A bolt of blue lightning leaps from your outstretched hand to an enemy within range, and then to an additional enemy within 10 feet, if available. Up to three targets take 3d8 <span style={{color: "#FF4"}}>Lightning</span> damage.</>

export const lighting_storm = <>A dark thundrous cloud spreads over a 50-foot radius around a point up to 100 yards away. Each target within the area takes 1d20 <span style={{color: "#FF4"}}>Lightning</span> damage.</>

export const storm_golem = <>Summon the mighty storm golem, the most powerful elemental entity which can be summoned and bidden.</>

export const hurricane = <>By the power of this ceremony, a mighty hurricane is formed and travels along the path you have ordained. Roll a d20. The category of the hurricane is as follows: <ul><li><b>1-9</b>:1</li><li><b>11-14</b></li><li><b>15-17</b>: 3</li><li><b>18-19</b>: 4</li><li><b>20</b>: 5</li></ul></>

export const detect_illusion = <>For one hour after casting the spell, you psychically discern the presence of illusions.</>

export const fleeting_illusion = <>You manifest a small illusion, which may have a physical and auditory component. The illusion may be used to lure, mystify, repel, or even assist the target. However, if the target passes a DT 16 <Sub skill="Perception" /> check, they are able to perceive the illusion.</>

export const illusory_disguise = <>For one hour, your face appears to change to match any face you have seen previously. Your clothes, stature, and body type do not change unless you also know the <AppendixLink appendix={1} target="illusory_being">Illusory Being</AppendixLink> spell. You may dismiss this spell at will before the duration is through. Anyone who scrutinizes your face may make a DT 18 <Sub skill="Perception" /> check to see past your disguise.</>

export const dispell_illusion = <>An illusion spell you have detected is permanently dispelled. Some illusions may make a saving throw based on the charisma of the caster.</>

export const illusory_being = <>You create an illusory being of any of the following types: <i>Beguiling</i>, <i>Terrifying</i>, <i>Distracting</i>, or <i>Ordinary</i>. The being appears in a location you can see, and obeys your telepathic command for the duration of the spell.</>

export const fools_invisibility = <>The target is filled with the inexplicable and illogical conviction that they are fully invisible.</>

export const mass_illusion = <>You create a powerful illusion visible from a great distance to any number of people. The visual has a</>

export const telempathy = <>You reach out and place the palms of your hands on either side of the target's forehead. While so positioned, you experience the emotions of the target as if they were your own. By mutual agreement, the target may also experience your emotions as well.</>

export const minor_telepathy = <>You read the thoughts of a creature within 100 feet of you. You may also impart your own thoughts into their mind. Unwilling targets make a DT 15 <Sub attr="CHA"/> saving throw to resist. If successful, they reject your contact and have advantage on willpower saving throws against your psychic spells for the next 24 hours.</>

export const major_telepathy = <>You establish a psychic connection with a being within range that you can see. You may read their thoughts, including those that the being is unable or unwilling to articulate. You may also impart your own thoughts into their mind. The spell lasts for as long as you continue concentration, or until the target breaks line of sight for ten minutes. If the target is unwilling, they may make a DT 15 willpower saving throw to resist. If successful, they reject your contact and have advantage on all willpower saving throws against you for the next 24 hours.</>

export const esoteric_telepathy = <>For 24 hours, you gain the ability to read the thoughts of an entity known to you by name, and may communicate with them telepathically. If at any point they become aware of your presence within their mind, they may make a DT 18 charisma saving throw to resist. If successful, they reject your intrusion and have advantage on all willpower saving throws against you for the next 24 hours.</>

export const psychic_sight = <>You see and hear through the senses of someone you can see, from a first person perspective. If the target has not consented to psychic contact, they make a DT 12 <Sub skill="Perception" /> saving throw to detect your presence. If this check succeeds, they may make a DT 15 <Sub attr="CHA"/> saving throw to reject your from their mind. Failing this, they can interfere with the spell by closing their eyes.</>

export const induce_emotion = <>Induce one of the following emotions in a target: calm, confusion, courage, fear, or rage.</>

export const inflict_amnesia = <>The the target fails a DT 17 <Sub attr="CHA"/> saving throw, they immediately forget their immediate surroundings and intentions.</>

export const hypnosis = <>You mesmerize a target that can see you, causing it to serve you in combat. If the target fails a DT 15 <Sub attr="CHA"/> saving throw, the spell takes hold and the target joins you in combat. If the target takes damage, they may repeat the saving throw.</>

export const mind_control = <>Take control of being you can see within range. You automatically gain the psychic sight and major telepathy. The target makes a DT 10 perception check to realize they are being psychically dominated. If the target succeeds, they may make an additional DT 18 willpower check to resist your control. If they succeed this check, the spell ends and they have advantage on similar checks against you. If it fails, they may make additional attempts to resist at the end of each of their combat turns, or before making actions significantly against their interests. Additionally, if the target is aware that they are being dominated, they may give subtle tells such as speaking with unnatural vocal inflections or eye twitches.</>

export const unimind = <>During the ceremony, all participants share a single mind such that the thoughts and emotions of each participant are instantaneously apparent to all others. Participants other than the caster must possess at least 12 <Sub attr="CHA"/> in order to participate in the ritual. The willpower cost is divided between all participants.</>

export const lesser_telekinetic_pull = <>A target weighing less than 20 pounds is drawn to the beckoning fingers of your outstretched hand. The object must be within 50 feet.</>

export const telekinetic_throw = <>Hurl an object or enemy captured by one of your telekinetic spells and make an <Sub skill="Accuracy" /> attack roll. If it hits, deal 2d8 <span style={{color: "#888"}}>Bludgeoning</span> damage. If the object thrown was already under your telekinetic control, you have advantage on the attack roll. If the object levitated was a dagger or spear etc, the damage type changes to <span style={{color: "#FFF"}}>Piercing</span>. The projectile's speed depends on the weight of the object. If the object weighs one pound or less, it moves at 200 ft/s. Otherwise, its speed is 200 ft/s divided by its weight in pounds.</>

export const levitate_object = <>An object weighing at most 1000 pounds responds to telekinetic impulse, rising to hover 3 feet above the ground. The object can be pushed or rotated while levitated without interrupting the spell.</>

export const shockwave = <>With a blast of psionic power, you deal 2d8 force damage to targets within the radius, knocking them back by 10 feet and causing them to fall <Tooltip tip={"Prone"}>The target cannot move or take actions that require both hands. DC is reduced by half. Ranged attacks against prone creatures have disadvantage.</Tooltip>. If a target makes a DT 13 <Sub skill="Defense" /> saving throw, it takes half damage and is not knocked prone. If a target rolls below a 9 on its saving throw, it also becomes <Tooltip tip={"Dazed"}>The target cannot take reactions, and has disadvantage on all saving throws.</Tooltip>.</>

export const levitation = <>While concentration is maintained, you hover roughly 3 feet above the ground, gliding above the terrain. You gain the <Tooltip tip={"Levitated"}>The target is levitating, unable to plant their feet firmly on the ground. The target cannot move by mundane means, or make melee attacks.</Tooltip> status and your <Sub attr="SPD"/> changes to 18. If the ground is more than 3 feet below, you may remain aloft or descend gracefully.</>

export const telemanipulation = <>Via subtle telekinetic impulses, the caster manipulates a target weighing less than 20 pounds with great precision, moving or rotating it at will. The object moves at a maximum speed of 5 ft/s and may not be rotated in such a way that any part of its outer boundary exceeds maximum speed relative to the center of mass. There is no limit to how many times this spell may be cast upon the same object or how much weight may be moved, provided all casters act in concert.</>

export const greater_telekinetic_pull = <>A <ChapterLink chapter={2} target="size">Medium</ChapterLink> or small creature is drawn just before your outstretched hands, at a rate of 10 ft/s. It gains the <Tooltip tip={"Levitated"}>The target is levitating, unable to plant their feet firmly on the ground. The target cannot move by mundane means, or make melee attacks.</Tooltip> status for as long as you maintain concentration. The target may make a DT 11 <Sub skill="Defense" /> or <Sub skill="Sorcery" /> saving throw to resist being pulled.</>

export const force_shield = <>Generate a shield of telekinetic force measuring six feet in diameter. The shield appears as a shimmering transparent pocket of air hovering in front of you. The shield grants partial cover and provides 7 Block Chance to up to two people standing behind it.</>

export const psyblast = <>Deal 4d6 <span style={{color: "#D00"}}>Force</span> damage to an enemy. If it fails a DT 16 <Sub skill="Mobility" /> saving throw, it is also knocked back 10 feet.</>

export const force_field = <>An invisible wall of telekinetic impulse appears in the chosen location. The wall prevents the passage of people and objects except for the spellcaster and allies. The wall can absorb 50+1d100 damage before concentration fails and the spell must be recast.</>

export const mind_armor = <>Generate a telekinetic suit of armor covering your entire body. The suit provides 10 BC initially, but loses 1 BC per hour until it vanishes.</>

